          '1841 年 6 月，林则徐被从重发往伊犁效力赎罪。赴戍途中经西安，他写下那句后来刻进民族记忆的诗：「苟利国家生死以，岂因祸福避趋之。」在新疆的两年多里，他勘察垦地、捐资兴修水利，推广坎儿井与纺车——当地人至今把那些井渠叫「林公井」。国家烧掉了他的功劳，他还给国家一眼井。',
