      '它是「世界性都市」的标本：西市有波斯邸、酒肆胡姬、景教寺院；日本平城京、渤海国上京龙泉府都是它的缩微复制品。白居易「百千家似围棋局，十二街如种菜畦」，写的就是这种棋盘式秩序。',
