          '守城的主力之一是热那亚将领朱斯蒂尼亚尼带来的七百职业兵，他与皇帝并肩指挥了几乎全程。5 月 29 日凌晨，总攻开始：巴什波祖克杂牌军、安纳托利亚军、近卫军耶尼切里三波冲锋，前两波被打退；关键时刻朱斯蒂尼亚尼中箭重伤、执意撤离，防线军心动摇。据载，城墙上有一扇小门科克波塔当晚未锁，奥斯曼士兵由此突入——千年都城，败给了一扇门。',
          '君士坦丁十一世脱下紫色皇袍，挥剑冲入乱军，尸骨无存。这位末代皇帝死得像一个罗马人：没有投降条款，没有流亡，用一场不可挽回的冲锋为千年帝国收尾。当天下午，穆罕默德二世骑马进入圣索菲亚大教堂——他做的第一件事，是把这座教堂改成清真寺。',
