          '但穆罕默德二世很快展示了他不属于「蛮族征服者」的那一面：三天后下令止掠，保护东正教会，任命修士根纳迪乌斯为新牧首，让正教会在奥斯曼治下以米勒特制度延续。他自己则采用了一个惊人的头衔——「罗马凯撒」。他不是来终结罗马的，是来继承罗马的。',
          '帝国的余脉随后逐一熄灭：特拉比松 1461 年陷落，伯罗奔尼撒紧随其后。另一条幽灵般的继承线却在北方展开：1472 年，莫斯科大公伊凡三世迎娶末代皇室的侄女索菲娅，双头鹰徽记北迁——「第三罗马」的说法从此挂在了莫斯科的城门上。',
