          '第三波在军事史：乌尔班巨炮示范了「任何城墙都可以被轰开」这个冷酷的新规则，欧洲的城市被迫发明低矮厚实、斜面卸力的棱堡，攻与守的技术军备竞赛从此提速，一场延续数百年的军事革命就此起步。攻城的人和守城的人，都从这座城的废墟里学到了各自的功课。',
