    paragraphs: [
      '1347 年 10 月，十二艘热那亚商船驶入西西里的墨西拿港。船员大多已死或在垂死中挣扎，身上带着溃烂的黑斑与肿块；港方慌忙命令船队离港，但为时已晚——老鼠与跳蚤已经上岸。此后五年，这批船捎来的东西杀死了欧洲约三分之一的人口，那是人类历史上最接近末日的一次。',
    ],
    sections: [
      {
        heading: '火药桶：一张疫病网络',
        paragraphs: [
          '鼠疫的老家在中亚的旱獭疫源地，原本与人类相安无事。十三世纪蒙古帝国把欧亚大陆缝成一张商路网，货物、使节与啮齿动物第一次可以畅通无阻地横穿大陆——丝绸之路运送的不只是丝绸，还有病原体。十四世纪中叶，疫病沿着商路一路向西点燃。',
          '1346 年，金帐汗国军队围攻克里米亚的热那亚商站卡法，军中疫病流行、久攻不下；据载蒙古人用投石机把染疫尸体抛进城内——这是史上最早有明确记载的生物战之一。城里的热那亚人弃城登船西逃，把死亡分装进了十二艘商船。',
          '此后是一张精确到可怕的传播时刻表：1347 年墨西拿、热那亚、威尼斯、马赛；1348 年横扫意大利与法兰西、登陆英格兰；1349 年德意志与低地；1350 年北欧；1351 年抵达俄罗斯——三年扫遍全欧。通行估计，欧洲人口损失三分之一到一半，约两千万人。',
        ],
      },
      {
        heading: '人们如何死去，又如何无解',
        paragraphs: [
          '病人腹股沟或腋下长出拳头大的肿块，高热、谵妄，皮肤出现黑斑，多数三五天内死去——腺鼠疫之外还有肺鼠疫，可直接人传人，冬天也不停手。十四世纪的医学对此毫无概念：四体液说的放血、熏醋与祈祷一个比一个无效，医生的处方最后只剩逃离。',
          '错误的应对火上浇油：教会组织大规模游行祈祷，人群聚集恰恰加速传播；船港封锁零星而迟缓，检疫制度根本不存在。中世纪的权威们面对的不是敌人，是一个他们连名字都叫不出的对手——疫情过后，人们才知道自己刚刚经历了什么的一半都不到。',
          '薄伽丘的《十日谈》开篇记录了佛罗伦萨的惨状：父母拒绝探望子女，夫妻互相遗弃，尸体像货物一样被抬出门。锡耶纳的编年史家阿尼奥洛·迪图拉留下的那句「我亲手埋葬了我的五个孩子」，是整场瘟疫最短也最重的碑文。',
        ],
      },
      {
        heading: '替罪羊与崩塌的秩序',
        paragraphs: [
          '找不到病原，社会就自己制造罪魁：犹太人被指控在井里投毒，从斯特拉斯堡到巴塞尔，数百个社区遭屠杀，斯特拉斯堡一地一夜处死数百人；教皇克莱孟六世两度发布通谕保护犹太人，地方上的火与刀却不听罗马的——权威的失灵，被所有人看在眼里。',
          '真正深远的后果在经济：人口锐减后，土地有余而人手奇缺，佃农与雇工的工资明显上涨；庄园主推动 1351 年《劳工法令》强行压价，反而激起反抗。农奴制在西欧加速松动，有经济史家干脆把黑死病称作封建制的意外掘墓人——瘟疫做了农民起义军想做而做不到的事。',
          '教会受的伤最重也最难愈合：神职人员冲在前线照顾病人，成批死去；补位者素质参差，布道与仪式的质量肉眼可见地滑落，鞭笞派的狂热游行又被教会自己出手镇压。权威一旦当众露怯，裂缝就再也合不上——两百年后宗教改革撕开的那道口子，此刻已经埋下了第一道纹路。',
        ],
      },
      {
        heading: '直接后果：艺术与制度的转向',
        paragraphs: [
          '文化的创伤刻进了图像：欧洲各地流行起「死亡之舞」——骷髅牵着教皇、皇帝与农夫共舞，人人平等，谁也不许缺席；墓碑雕刻从安睡的纪念像换成半开棺的腐尸像，连主教的坟前都不再遮掩。中世纪艺术第一次集体直视腐烂——那不是审美趣味，是一整代人的心理创伤记录。',
          '文学与心态同步转向：薄伽丘笔下的人不再等待来世，而是热气腾腾地讲故事、谈恋爱、嘲讽教会——对现世生活的珍视明显上升。有史家（不无争议地）把这种心理转折列作文艺复兴的隐秘前奏：先学会向死而生，才谈得上重新发现人。',
          '制度上倒是留下了一件真正管用的发明：威尼斯设立卫生委员会，拉古萨（今杜布罗夫尼克）1377 年规定来船须先在港外停泊三十天，后延长为四十天——意大利语 quaranta giorni，今天英语 quarantine（隔离）一词的直系祖先。现代公共卫生，是从这场大溃败的灰烬里长出来的。',
        ],
      },
      {
        heading: '长程影响：微生物才是边界改变者',
        paragraphs: [
          '鼠疫从未离开：1665 年伦敦大疫，十九世纪末第三次大流行经香港传向全球各大港口。直到 1894 年，耶尔森在香港分离出鼠疫杆菌——人类这才第一次知道五百年前那位对手的名字。名字知道得再晚，也总比没有强：防治体系从此才真正起步。',
          '更长的链条在经济史与社会结构里：劳动力议价能力的跃升、消费结构的变化、继承使财富更集中又更流动——有学者认为，黑死病把西欧从马尔萨斯陷阱的原点推离了一步，为几个世纪后的近代增长悄悄挪开了第一块石头。这不是瘟疫的功劳，但确实是瘟疫的遗产。',
          '1347 年那几艘船证明了一件事：改写历史的未必是帝王将相，一只带菌的老鼠搭上商船就够了。微生物才是人类史上最沉默也最高效的边界改变者——1519 年它在美洲重演一遍，2020 年又在全世界面前重演一遍。人类每次都说记住了，其实只是轮到下次再听。',
        ],
      },
    ],
