          '查理坐得住。768 年继位后三十余年戎马：平定阿基坦，吞并伦巴第，击退阿瓦尔，把疆土推至今法、德、荷、比、瑞士与北意。萨克森战争打了三十二年，强制皈依伴随血腥，据载 782 年曾一日处决四千五百名降卒；778 年远征西班牙的败仗龙塞斯瓦列斯，反而被吟游诗人写成《罗兰之歌》——史实平平，史诗轰轰烈烈。',
