    region: 'americas',
    year: 1492,
    kicker: '两个世界的碰撞',
    summary: '1492 年起，作物、疾病与人口在全球尺度上大洗牌。',
    paragraphs: [
      '1492 年 10 月 12 日凌晨，平塔号桅顶的瞭望员喊出「陆地！」——三艘船、约九十人在海上漂了五周后，哥伦布踏上巴哈马的一处滩涂，坚信自己到了亚洲的边缘。他到死都没承认自己错了，但这个错误连接了分离一万多年的两个世界。此后半个世纪，物种、疾病、人口与白银在地球两侧对调——没有人下达命令，也没有人看懂全局，人类历史上最大的一次生态与社会重组，就此开始。',
    ],
    sections: [
      {
        heading: '火药桶：一条误算出来的航线',
        paragraphs: [
          '动力来自旧大陆的焦虑：奥斯曼控制东地中海后，香料贸易的成本与关卡层层上涨；葡萄牙选择沿非洲南下绕行，西班牙则押注一个热那亚人的大胆误算——哥伦布采用了偏小的地球周长数据，坚信亚洲就在大西洋对岸不远处。1484 年葡萄牙拒绝了他，1492 年刚完成收复失地运动的西班牙双王决定赌这一把：国库空虚的帝国，最不缺的就是赌性。',
          '航行本身平淡得像一次外派：三艘船、约九十人，8 月 3 日从帕洛斯出发，在加那利群岛补给后西行，五周后见岸。哥伦布带去的是西班牙旗帜与一封致中国大汗的国书，带回的是几箱金饰、鹦鹉、烟草样品和六个自愿跟随的泰诺人——他以为自己发现了通往东方的边门，实际打开的是两个世界的闸门。',
          '日志里早就藏着预告：哥伦布写道，这些岛民民风淳朴、毫无武器，「凭五十个人，就能把他们全部征服，随我们的需要驱使」。大交换的第一份文书，同时就是殖民的第一份计划书——连接与掠夺，从第一天起就在同一页纸上。',
        ],
      },
      {
        heading: '经过：两个半球的对调',
        paragraphs: [
          '旧大陆送去的不只是人，而是一整支生物侵略军：猪、牛、马、羊、小麦、甘蔗，以及天花、麻疹、流感、斑疹伤寒。美洲人一万多年未曾接触这些病原，免疫系统一片空白；1518 年前后天花在中部美洲大流行，直接为科尔特斯的几百名士兵开了城门。',
          '人口代价是灾难级的：学界估计，一个世纪内美洲原住民人口损失约九成——从数千万级跌到数百万级。阿兹特克与印加帝国的陷落，一半靠枪炮与阴谋，另一半靠病毒：皮萨罗用一百六十八人俘虏了拥兵数百万的印加皇帝，数学上最合理的解释不在武器里，而在他的士兵早已把天花带到了之前的沿海。',
          '反向的输出则安静得多，也深远得多：玉米、土豆、红薯、番茄、辣椒、花生、烟草陆续登陆旧大陆。土豆让北欧的人口曲线陡然上扬；玉米与红薯在中国上山下滩，塞进水稻小麦够不着的旱地——清代人口从一亿冲到四亿，燃料里有相当一部分是美洲作物。历史学家何炳棣最早系统论证了这条链：饭碗换了，版图与人口跟着换。',
        ],
      },
      {
        heading: '代价：白银、矿坑与价格革命',
        paragraphs: [
          '大交换还有第三条线：白银。1545 年波托西银矿发现，殖民当局用印加传统的米塔劳役制驱使原住民下井，矿坑被称为「地狱的入口」；一个世纪内，全球白银近半产自美洲。这些白银兵分两路流遍世界：一路过大西洋进欧洲，一路经阿卡普尔科装上马尼拉大帆船，直航中国。',
          '中国恰好处在白银货币化的当口：1581 年张居正推行一条鞭法，赋税折银缴纳，明帝国成了全球白银最大的吸铁石。据估计，明末经马尼拉与欧洲两条线流入中国的白银约占同期全球产量三分之一到一半——美洲的矿工、马尼拉的中转、江南的市集，被同一艘船的航线缝在一起。',
          '账单同样全球化：波托西的原住民矿工、种植园里的非洲奴隶（跨大西洋奴隶贸易自此全面展开）、以及被物价革命灼伤的欧洲穷人——十六世纪西班牙物价上涨三四倍。大交换的第一批成本，由三个大陆的底层分别支付；收益的流向，从来和代价的流向相反。',
        ],
      },
      {
        heading: '长程影响：谁也没有看懂的世界',
        paragraphs: [
          '知识层面，新大陆的存在本身就是一记重拳：托勒密的地理、古典的博物学、圣经的族谱，全都要为新半球腾位置——旧大陆的经验第一次明显不够用了。欧洲的知识权威从这场对调开始松动，科学革命的地基里，有一块砖叫「美洲」。',
          '1972 年，环境史家克罗斯比给整个过程命名「哥伦布大交换」，从此这场持续五百年的物种对流有了学名。今天的餐桌上，辣椒炒土豆、玉米排骨汤、花生与番茄，全都是 1492 年的移民后代；你每天喝的咖啡长在美洲或非洲，抽的烟、吃的巧克力同样如此——世界餐桌是被 1492 年重新写好的。',
          '大交换也从未结束：它只是从帆船的船舱搬进了集装箱和货运航班。物种入侵、疫病全球传播、产业链全球分布——连接即交换，交换即重组，这条规则五百年没变过。1492 年的参与者没有一个真正理解正在发生什么；今天的我们看见了全景，却依然管不住每一次新的交换——这是大交换教给人类的、至今没学会的一课。',
        ],
      },
    ],
