          '神学的火药早已备好。路德在研读《罗马书》时豁然开朗：经上说「义人必因信得生」——得救靠上帝的恩典与人的信仰，不靠善功的累积，更不靠一张纸的购买。一旦接受这条，赎罪券就不只是腐败问题，而是神学错误：它把免费的东西标了价，而标价的人无权标价。',
          '改革呼声也不是新闻：一百年前波希米亚的胡斯就因类似主张被处以火刑，更早还有英格兰的威克里夫。前人缺的不是真理，是传播速度——胡斯没有印刷机，路德赶上了：古腾堡的活字印刷问世不过半个多世纪，德意志印坊林立。论纲在等印刷机，印刷机也在等论纲；两者相遇，辩论就变成了爆炸。',
