          '1939 至 1941 年是轴心国的狂飙期：波兰抵抗月余而亡，闪击战首次亮相即震动世界；1940 年法国六个星期崩溃，马其诺防线成了军事史上最大的嘲讽；不列颠空战挡住海峡，是当年的第一个「不」。1941 年 6 月巴巴罗萨行动入侵苏联，12 月珍珠港遇袭、美国参战——战争的全球化，在这一年完成。',
          '转折发生在 1942 至 1943 年，三次心跳：中途岛海战（1942 年 6 月）日本四艘主力航母沉没，太平洋攻守易手；斯大林格勒战役鏖战近半年，1943 年 2 月德国第六集团军九万余人被俘，东线从此倒转；阿拉曼战役（1942 年 11 月）锁死北非。三次心跳之后，轴心国剩下的选项只有撤退。',
