          '清算方式的转变是这场战争唯一的亮色：纽伦堡与东京审判没有沿用战胜国的即决处决，而是第一次以法庭、证据与辩护程序审判战争罪行，「反人类罪」「破坏和平罪」自此进入法律词典——用法律而非子弹清算战争，是文明在废墟上能拿出的最大诚意。',
          '物质与心理的废墟难以计数：欧洲工业带成瓦砾，日本六十余城被烧成白地，数千万流离失所者游荡在 1945 年的公路上——史家称之为「零年」。对「绝对战争」的恐惧，成了战后整整一代人的共同心理底色，此后所有国际制度的潜意识里都写着四个字：不能再打。',
