          '地图同步重画：欧洲殖民帝国在战争中被严重削弱，去殖民化大潮随之涌起，此后三十年八十余国独立建国；世界权力的重心从伦敦巴黎移向华盛顿与莫斯科，铁幕降下，热战换冷战。战争结束了，对峙才刚刚开始——只是这一次，对峙被国际制度与核武器一起冻住，成了如今这种打不起也放不下的冷战。',
          '核时代是最后的转折：1945 年 7 月 16 日「三位一体」核试验成功，数年内苏、英、法、中相继拥核，「相互确保摧毁」反而冻结了大国间的直接热战。核威慑是最昂贵的和平：七千万条生命换来的教训加上同归于尽的概率表，把「再也不能这样打」从愿望变成了算术。',
