          '技术分岔延续至今：图灵的解码机催生现代计算机，V-2 火箭的技术谱系通向登月，核物理分裂出能源与医学的同位素应用，雷达与青霉素早已日常化——二战是现代科技的助产士，我们至今没有断奶。今天每一部智能手机里，都有 1940 年代那场战争的军费。',
