          '转折发生在公元前 476 年之后：希波战争胜利，奥运会成了希腊叙事的加冕礼；再往后，马其顿的腓力与亚历山大先后包揽冠军，罗马吞并希腊后比赛照办——只是冠军越来越出自职业选手与赞助人，皇帝尼禄甚至亲自下场参加战车赛并「获得」冠军。业余的理想，从未真正统治过赛场。',
