          '代价清单：古代奥运没有留下任何奖杯——冠军的奖品是橄榄枝、颂歌、雕像与家乡的终生供给；留下的是品达的颂诗、数百条运动员铭文与被泥沙完好保存的雕像群。1875 年德国考古队挖开奥林匹亚，出土的雕塑让全欧洲惊叹，「奥运会」三个字重新进入人类的词典。',
