          '古代奥运留给现代的两件遗产同样真实：「神圣休战」的理念——联合国自 1993 年起每届重申奥林匹克休战；以及「以竞技代替战争」的希腊式想象。赛会停了一千五百年，但它证明过一件事：哪怕最能打的民族，也愿意为一场比赛放下武器——这比任何奖牌都值钱；现代世界的体育外交与休战呼吁，都从这里抄过作业。',
