          '转折在于，巴格达没有停留在翻译：花剌子米把印度数字与希腊代数杂糅，写出《代数学》——algorithm 与 algebra 两个英文词的祖先都出自这本书；金迪研究光学，巴塔尼修正托勒密的岁差。翻译运动的真正产出是再创造：书进来，科学出去——输入是希腊的，输出是全世界的。',
