          '1258 年蒙古人攻陷巴格达，屠城数日，末代哈里发被裹进地毯纵马踩死。一句流传甚广的记载说，底格里斯河被染黑又染红——染黑的是墨水，染红的是血；纵有夸张，结局是真实的：智慧宫的原址，连一块石头都没能留下来，后人只能靠文献想象它的书架。',
