          '技术扩散的门槛恰恰在此：纸是工艺，不是货物。搬不走厂房，但搬得走工匠——舂浆、抄帘、烘墙，每一道工序都长在人身上。所以在那个时代，一项技术越过国境最常见的方式，不是许可证贸易，而是工匠本人的迁徙——无论自愿，还是被迫。',
