          '官学也随之下移。「学在官府」的垄断被打破，孔子开私学之先，「有教无类」让平民第一次拿到进入辩论场的门票。思想市场的出现，前提是人才市场的出现——这是百家争鸣最容易被忽略的经济学起点。私学把学问变成了可以随人迁徙的资产。',
