          '道家选择退出赛道：老子讲无为而治、道法自然，庄子讲逍遥与齐物——对政治冷眼旁观，对个人全力松绑。三家的分歧点极清晰：人性是什么，秩序从哪来，政府该管多宽。此后中国政治哲学的全部争论，都是这三问的变奏——换今天的术语，这是三场平行的制度设计实验。',
