          '朱罗王朝此时正如日中天：罗茶罗乍一世（985 — 1014）统一南印度、征服斯里兰卡北部；其子拉金德拉一世继续扩张，甚至北征恒河流域。朱罗商人同时深度参与对华贸易——1015 年，注辇（中国史书对朱罗的称呼）使团抵达宋真宗的宫廷，带回关于东方大市场的第一手情报。但当朱罗商船途经海峡被层层抽税时，矛盾就变成了国家间的账目。',
