          '这场传播有个冷峻的注脚：发明者自己退场了。腓尼基城邦先后臣服于亚述、巴比伦与波斯，推罗被围困毁城，迦太基在前 146 年被罗马夷平——布匿语与布匿文随之消亡。今天没有哪个国家说腓尼基语，它的名字主要活在两个地方：字母谱系表的第一行，和英语 alphabet 一词的词源（Aleph 与 Bet，正是这套字母的头两个字母）。',
          '希腊史家希罗多德记载，字母由腓尼基人「随商队」带进希腊，希腊人称之为「腓尼基字母」——远古的当事人比后世学者诚实。技术史上反复上演的剧本在三千年前就已写好：发明者未必是最大受益者，工具离开母体后，走的是需求的方向。',
          '被抢走的火种烧得更旺，这不算安慰，算规律。腓尼基人失去了一切，除了被全人类抄走的作业。',
