          '明治维新从此成为所有后发国家的教科书：清末的新政与立宪、土耳其的凯末尔改革、朝鲜的近代化计划，都对着同一本日本案例做笔记。它证明了一件事——锁国的农业国可以在一代人内完成制度与产业的整体置换，前提是统治集团自己愿意交出旧特权。',
          '它同时是警告牌：没有制衡的加速度终有方向问题。「富国强兵」的路径一旦与「统帅权独立」结合，胜利只会喂大军队的胃口——1931 年九一八、1937 年全面侵华、1945 年战败投降，源头都埋在明治宪法的那条裂缝里。学习日本的中国与朝鲜，学到一半也被迫先面对它的炮口。',
          '1868 年颁布的《五条誓文》第一条就写明「广兴会议，万机决于公论」，第五条「求知识于世界，大振皇基」。前者被后来的军部背叛，后者被认真执行了三十年。明治维新的全部经验可以压成一句话：后发者学得会技术，最难的是同时学会约束技术背后的权力。',
