          '代价先于荣耀到来。1967 年 1 月，阿波罗 1 号在地面测试中起火，三名宇航员——格里索姆、怀特、查菲——在二十秒内殉职。事故逼出彻底的设计返工：舱门改为向外开，舱内材料全部换成阻燃品。此后每一次成功的背后，都站着这次失败。',
          '1969 年 7 月 16 日，阿波罗 11 号发射；20 日，登月舱「鹰」下降。警报灯忽然亮起（计算机过载报警 1202），阿姆斯特朗发现自动目标点满是乱石，手动操纵避让，着陆时燃料余量只够约三十秒。指挥中心随后宣布：「鹰已着陆。」——那三十秒，是八年间几十万人神经的总和。',
