          '更抽象的遗产是方法论：把一个不可能的目标拆成几十万个可验证的子任务，用系统工程管理几十万人的协同——这套「登月工程学」此后被搬进曼哈顿之外的每一个大项目，从人类基因组到移动互联网。',
          '而它最深的启示是政治性的：人类可以在八年内走到月球，只要一个社会足够想要——但这样的社会意志，政治只买得起一次。阿波罗的墓志铭应当这样写：它证明了极限在哪里，也证明了没有对手的时候，极限有多远。月球上的脚印还在，等下一个愿意为远途付费的时代。',
