          '真正的引爆点在 2008 年：App Store 上线，第三方开发者第一次被邀请上桌，三七分成模式让全球程序员都成了苹果生态的工人。「有个 App 能干这个」成了新口头禅——手机的能力边界从此由全球开发者共同扩张。同年谷歌开源 Android，三星、HTC 与后来的小米、华为把智能机推向每个价位段。',
          '胜负手在十年内揭晓：诺基亚的功能机帝国在 2013 年把手机业务售予微软，黑莓退守企业市场。功能机不是输在质量——它输在用户突然不再要求质量，而是要求生态。',
