          '最深远的叠加是支付。肯尼亚 2007 年的 M-Pesa 证明手机可以当账户用；中国自 2013 年前后普及二维码支付，钱包与现金在几年内从日常场景中退场。发展中国家凭手机「跳级」——跳过固定电话直入移动通信，跳过信用卡直入移动支付，跳过 PC 直入互联网。基建的后发优势，第一次以十年为单位兑现。',
          '社交应用随平台同步进化：2011 年微信上线，把聊天、支付、小程序装进一个「超级应用」；Facebook 与 Instagram 定义了欧美范式。手机不再只是通讯工具，成了社会运行的界面。',
