          '信息环境同步变质。2018 年 MIT 的研究发现，假消息在社交网络上的传播速度显著快于真消息——真相在结构上跑输了谣言。位置数据被画像成精准广告，隐私成为默认支出；「离线」从一个默认状态，变成需要意志力练习的能力。',
          '这是技术史的老命题的新版本：工具放大人的意图，善与恶同时放大。智能手机没有制造贪婪与轻信，它只是把两者的传播成本降到了接近零。',
