          '技术链条继续向下延伸：智能手机是人工智能时代最大的数据入口与终端出口，扫码、刷脸、语音助手，AI 时代的许多日常形态先在手机上排练。回头看，2007 年那台没有键盘的机器，是此后所有智能终端的母版。',
