          '申办的挫折更近：1993 年蒙特卡洛投票，北京以两票之差败给悉尼，举国愕然。八年后的 2001 年 7 月 13 日，莫斯科，萨马兰奇拆开信封念出「Beijing」，电视机前的中国街头瞬间变成海洋——那一年，改革开放红利正在兑现，申办成了一个国家递给世界的名片。',
          '为了这一天，北京准备了七年：机场第三航站楼、鸟巢与水立方相继落成，地铁运营线路从两条增至八条。城市像考生赶考前夜，把能刷的题全刷了一遍。',
