          '开幕式被国际媒体反复回放：缶阵倒计时、画卷徐徐展开、活字印刷方阵起伏如波浪。它把国家叙事做成了视听产品，此后十年全球大型活动的开幕式都在有意无意地模仿它——包括后来的冬奥与亚运。',
          '七万名赛会志愿者与四十万名城市志愿者被外媒称作「微笑长城」，「鸟巢一代」从此成为中国年轻世代的代名词——这可能是奥运留给中国最软、也最持久的遗产。',
