    region: 'europe',
    year: 2015,
    range: [2015, 2016],
    kicker: '把升温锁在两度内',
    summary: '196 国承诺控温目标，全球气候治理第一次全员到齐。',
    paragraphs: [
      '2015 年 12 月 12 日晚，巴黎北郊布尔歇展览中心，法国外长法比尤斯落槌：《巴黎协定》在 196 个缔约方全票通过，全场起立鼓掌数分钟。人类历史上第一次，所有主要排放国坐进同一间屋子，签下同一份带数字的承诺——把全球升温控制在 2 摄氏度以内，力争 1.5 摄氏度。',
    ],
    sections: [
      {
        heading: '火药桶：二十年谈判与一次惨败',
        paragraphs: [
          '科学线索埋了一个多世纪：1896 年阿伦尼乌斯就计算出二氧化碳翻倍会让地球升温约五度；1958 年基林曲线开始记录大气二氧化碳的爬升；1988 年 IPCC 成立，把「人类致暖」从论文变成全球议题。',
          '谈判史却是一连串挫败：1992 年里约公约只有原则没有牙齿；1997 年《京都议定书》只约束发达国家，美国签了不批，加拿大干脆退出；2009 年哥本哈根峰会彻底崩盘——大会文件被五国闭门密拟，穷国怒斥不透明，会议以「注意到」这份最弱的措辞收场。此后数年，气候外交进入冰河期。',
          '法国人接手后换了打法：外长法比尤斯与谈判代表蒂比亚娜提前一年周游列国，一对一看需求；会议程序上坚持透明全会，不给「密室文件」口实。谈判桌外，岛国联盟与欧盟、美国悄悄结成「雄心联盟」，把 1.5 度目标从边缘诉求变成了正文。',
        ],
      },
      {
        heading: '经过：一个词与一记槌',
        paragraphs: [
          '协定的核心设计叫「国家自主贡献」：不强制分配指标，各国自己报减排方案，每五年盘点一次并递进加码——哥本哈根的失败教训被写成了机制：没人能强迫别人，但所有人都能看见彼此。加上气候资金、透明度框架与损失损害条款，196 方各取所需。',
          '通过前一刻还出了戏剧：美方法律顾问发现协定 4.4 条的「应当」按国际法可能让条约变成强制义务，触发美国参议院批准程序——全场紧急进行口头修正，把「应当」改成「应该」。一字的改动，保住了协定免于美国国内的政治绞肉机。',
          '生效速度同样破纪录：2016 年 4 月开放签署，11 月 4 日即达到「55 国且占全球排放 55%」的双门槛正式生效——联合国多边条约史上最快的生效之一。这背后有中美的默契：两国在 G20 期间同步交存文书，给犹豫者背书。',
        ],
      },
      {
        heading: '代价与考验',
        paragraphs: [
          '第一场大考来自美国自己：2017 年特朗普宣布退出，2020 年 11 月 4 日正式生效——恰是拜登胜选次日；2021 年美国重新加入。四年折腾留下的不是政治账，而是减排窗口期的账：全球排放没有等任何人。',
          '更冷的考卷是数字：各国承诺加总后，本世纪末升温仍指向约 3 摄氏度，与 1.5 度目标之间的差距逐年扩大；2024 年成为第一个全年平均升温超过 1.5 摄氏度的年份（联合国气象机构确认）——单年突破不等于永久越线，但沙漏的流速肉眼可见。',
          '资金是另一道裂缝：发达国家「每年一千亿美元」的承诺年年拖欠，谈判桌上「共同但有区别的责任」的争吵三十年未变。2022 年 COP27 终于同意设立损失与损害基金——为已是废墟的国家付账的机制，迟到了三十年，但毕竟成立。',
        ],
      },
      {
        heading: '长程影响：把地球当项目来管',
        paragraphs: [
          '巴黎最重要的遗产是范式：全球第一次用同一套会计语言盘点同一颗行星——所有国家每年报数、每五年互查，排放数据成了像 GDP 一样的国家指标。2023 年的首次全球盘点照章运转，2022 年的联合国生物多样性框架直接套用了巴黎式结构。',
          '执行的工具箱在此期间悄悄换血：光伏度电成本十年间下跌近九成，风电、电动车、储能卷成产业竞赛，中国建成的光伏产业链与欧洲的碳市场、美国的《通胀削减法案》成了三条不同的执行路径——减排第一次比拖延更便宜，这是巴黎之后经济地理里最大的变化。',
          '巴黎协定的本质是一份预期管理文件：它不命令任何人，只让所有人在同一张表上互相看见。气候治理的下半场——谁加速、谁赖账、谁为损失付钱——都要在这张表上解决。一份让 196 方都嫌不够、又都肯签字的文本，本身就是这个分散的世界能达成的最大公约数。',
        ],
      },
    ],
